  "about.p1": "YaarLink started with a simple observation in Punjab: small shops were paying for pamphlets nobody read, while local meme pages with 100K followers had no way to earn. Brands wanted creators. Creators wanted brands. Nobody wanted complicated dashboards.",
  "about.p2": "So we started coordinating — manually at first. WhatsApp groups, Excel sheets, late-night Story checks. Over time that grew into a network of pages in every region — Punjabi meme pages, Hindi city pages, South Indian creators, Bengali and Marathi communities, and international influencers — running paid promotions for cafes, apps, events, local shops and global brands.",
  "about.v1": "Human first",
  "about.v1d": "We talk like yaars, not like a SaaS sales team. Call us, WhatsApp us. We reply.",
  "about.v2": "No fake numbers",
  "about.v2d": "We will never show “10,000 brands” or stock-photo testimonials. Only real campaigns.",
  "about.v3": "Indian by default",
  "about.v3d": "Punjabi, Hindi, Hinglish. UPI budgets. Small-town shops, not just Delhi startups.",
  "about.where": "Where we are going",
  "about.nowLabel": "Now",
  "about.nextLabel": "Next",
  "about.laterLabel": "Later",
  "about.dreamLabel": "The dream",
  "about.now": "Manual listing review, creator profiles & campaign dashboard in 3 languages",
  "about.next": "Better discovery, more languages, clearer collaboration tools",
  "about.later": "Smart matching, performance analytics, more languages",
  "about.dream": "Voice campaign creation — “friend, promote my shop”",
  "about.ctaTitle": "Want to build with us?",
  "about.ctaBody": "We are onboarding our first {brands} brands and {creators} creators personally.",
  "about.join": "Join YaarLink →",
  "about.talk": "Talk to us",

  /* about page — problem stories */
  "about.stories.eyebrow": "The real problems",
  "about.stories.title": "Behind every connection, there's a problem worth solving.",
  "about.stories.intro1": "Not every business has a big marketing budget. Not every creator knows how to find paid opportunities. And not every growing brand has the time to manage dozens of collaborations.",
  "about.stories.intro2": "These are the everyday problems we're building YaarLink to solve.",
  "about.s1.cat": "Local businesses",
  "about.s1.title": "The shop that nobody discovers",
  "about.s1.p1": "A local café makes great coffee. A clothing shop has a new collection. A small business has something worth sharing.",
  "about.s1.p2": "But getting noticed online isn't easy.",
  "about.s1.p3": "Hiring an agency may be too expensive, finding the right local creator takes time, and spending money on promotions without knowing who they reach can feel like a gamble.",
  "about.s1.take": "“We believe local businesses deserve a simpler way to discover creators who understand their audience and community.”",
  "about.s2.cat": "Independent creators",
  "about.s2.title": "The creator behind the screen",
  "about.s2.p1": "A creator spends hours making content, building an audience, and keeping people entertained.",
  "about.s2.p2": "Their page might have a strong local following, an engaged community, or a unique regional voice. But finding brands willing to work with them can be difficult.",
  "about.s2.p3": "They don't necessarily need millions of followers. Sometimes, they just need the right opportunity.",
  "about.s2.take": "“We want to make it easier for creators to showcase their work, discover relevant campaigns, and connect with brands.”",
  "about.s3.cat": "Growing brands",
  "about.s3.title": "When growing becomes complicated",
  "about.s3.p1": "A brand decides to work with several creators.",
  "about.s3.p2": "Soon, conversations are scattered across WhatsApp, prices are written in spreadsheets, deadlines are approaching, and someone is still waiting for a reply.",
  "about.s3.p3": "The problem isn't always finding creators. It's keeping everything organized.",
  "about.s3.take": "“We're working towards a simpler way to discover creators, organize campaigns, and manage collaborations in one place.”",
  "about.stories.note": "Everyday scenarios we hear from shops, creators and brands — shared to explain why we're building YaarLink, not as customer case studies.",
  "about.stories.banner": "A business shouldn't have to be big to reach the right people. A creator shouldn't have to be famous to find an opportunity.",
  "about.stories.bannerSub": "We're building YaarLink to help bring them closer together.",

  /* how it works page */
  "howp.eyebrow": "No jargon, promise",
  "howp.title": "How YaarLink works",
  "howp.sub": "Simple enough for a local shop. Powerful enough for a growing brand.",
  "howp.1t": "Tell us what you need",
  "howp.1d": "Brand fills a 3-minute form: what are you promoting, who should see it, which language, what budget. YaarLink manually reviews the campaign before it is public, and its status stays in the dashboard. Write like you speak — English, Hindi or Punjabi all okay.",
  "howp.1e": "Example: “Cafe near PAU gate, want 5 Ludhiana pages for Story promos this weekend, budget ₹8,000.”",
  "howp.2t": "Find the right creators",
  "howp.2d": "Browse reviewed creators by language, city, category and content type. YaarLink does not use smart matching; for manual suggestions, message the team on WhatsApp.",
  "howp.2e": "Filters: Punjabi • Ludhiana • Meme page • Story",
  "howp.3t": "Agree details off-platform",
  "howp.3d": "There is no in-app chat. Use the contact shared through the application to confirm content, dates, price, usage rights, any draft check, post proof and payment before work starts.",
  "howp.3e": "If you want a preview, exchange drafts or screenshots directly before posting.",
  "howp.4t": "Check proof, then record completion",
  "howp.4d": "The creator sends the post link, screenshots and any results through the agreed off-platform channel. YaarLink does not collect or verify views, clicks, enquiries or sales. After checking, the brand can mark the application complete in the dashboard.",
  "howp.4e": "Keep post links, screenshots and payment receipts in your own records.",
  "howp.forBrands": "For brands",
  "howp.b1": "1. Create campaign →",
  "howp.b2": "2. Review applications in your dashboard",
  "howp.b3": "3. Agree price & deliverables off-platform",
  "howp.b4": "4. Check proof, then mark complete",
  "howp.startBrand": "Start as brand →",
  "howp.forCreators": "For creators",
  "howp.c1": "1. Create profile →",
  "howp.c2": "2. Browse campaigns",
  "howp.c3": "3. Apply from a campaign",
  "howp.c4": "4. Agree fee & payment, then post",
  "howp.startCreator": "Join as creator →",
  "howp.scopeTitle": "What happens on YaarLink — and what happens off it",
  "howp.scopeOnTitle": "On YaarLink today",
  "howp.scopeOn1": "Manual review of campaigns and creator profiles before public listing",
  "howp.scopeOn2": "Campaign/profile management and application statuses in dashboards",
  "howp.scopeOn3": "In-app notifications for application activity; marketplace emails are best effort",
  "howp.scopeOffTitle": "Off YaarLink / manual",
  "howp.scopeOff1": "Chats, quotes, negotiations and payments",
  "howp.scopeOff2": "Draft checks, posting links, screenshots, results and performance records",
  "howp.scopeOff3": "Team replies on WhatsApp, Instagram, phone or email — timing is not guaranteed",

