  "about.eyebrow": "हमारी कहानी",
  "about.title": "सबके लिए आसान मार्केटिंग।",
  "about.p1": "YaarLink की शुरुआत पंजाब में एक साधारण नज़र से हुई: छोटी दुकानें उन पर्चियों पर पैसे खर्च कर रही थीं जो कोई नहीं पढ़ता, जबकि 100K फॉलोअर्स वाले लोकल मीम पेजों के पास कमाने का कोई ज़रिया नहीं था। ब्रांड को क्रिएटर चाहिए थे। क्रिएटर को ब्रांड। मुश्किल डैशबोर्ड कोई नहीं चाहता था।",
  "about.p2": "तो हमने संपर्क करना शुरू किया — पहले हाथ से। WhatsApp ग्रुप, एक्सेल शीट, रात भर की स्टोरी चेकिंग। धीरे-धीरे यह हर क्षेत्र के पेजों का नेटवर्क बन गया — पंजाबी मीम पेज, हिंदी सिटी पेज, साउथ इंडियन क्रिएटर्स, बंगाली और मराठी कम्युनिटी, और इंटरनेशनल इन्फ्लुएंसर — जो कैफे, ऐप, इवेंट, लोकल दुकानों और ग्लोबल ब्रांड के पेड प्रमोशन करते हैं।",
  "about.v1": "इंसान पहले",
  "about.v1d": "हम यारों की तरह बात करते हैं, SaaS सेल्स टीम की तरह नहीं। कॉल करें, WhatsApp करें। जवाब मिलेगा।",
  "about.v2": "नकली नंबर नहीं",
  "about.v2d": "हम कभी “10,000 ब्रांड” या स्टॉक-फोटो टेस्टिमोनियल नहीं दिखाएँगे। सिर्फ़ असली कैंपेन।",
  "about.v3": "भारत से",
  "about.v3d": "पंजाबी, हिन्दी, हिंग्लिश। UPI बजट। सिर्फ़ दिल्ली के स्टार्टअप नहीं, छोटे शहर की दुकानें भी।",
  "about.where": "हम कहाँ जा रहे हैं",
  "about.nowLabel": "अभी",
  "about.nextLabel": "अगला कदम",
  "about.laterLabel": "आगे",
  "about.dreamLabel": "सपना",
  "about.now": "3 भाषाओं में मैन्युअल लिस्टिंग जाँच, क्रिएटर प्रोफ़ाइल और कैंपेन डैशबोर्ड",
  "about.next": "बेहतर खोज, और भाषाएँ, सहयोग के स्पष्ट साधन",
  "about.later": "स्मार्ट मैचिंग, परफ़ॉर्मेंस एनालिटिक्स, और भाषाएँ",
  "about.dream": "आवाज़ से कैंपेन — “यार, मेरी दुकान प्रमोट कर दे”",
  "about.ctaTitle": "हमारे साथ बनाना चाहते हैं?",
  "about.ctaBody": "हम पहले {brands} ब्रांड और {creators} क्रिएटर्स को व्यक्तिगत रूप से जोड़ रहे हैं।",
  "about.join": "YaarLink से जुड़ें →",
