  "howp.scopeOn2": "डैशबोर्ड में कैंपेन/प्रोफ़ाइल प्रबंधन और आवेदन स्थितियाँ",
  "howp.scopeOn3": "आवेदन गतिविधि के लिए इन-ऐप सूचनाएँ; मार्केटप्लेस ईमेल सर्वोत्तम प्रयास पर भेजे जाते हैं",
