  "how.1d": "ਕੀ ਪ੍ਰਮੋਟ ਕਰਨਾ ਹੈ? ਕਿਸਨੂੰ ਦਿਖਣਾ ਚਾਹੀਦਾ ਹੈ? ਕਿਹੜੀ ਭਾਸ਼ਾ ਵਿੱਚ? ਕਿੰਨੇ ਬਜਟ ਵਿੱਚ? 3 ਮਿੰਟ ਲੱਗਣਗੇ।",
