  "privacy.campaignNotice": "ਕੈਂਪੇਨ ਵੇਰਵੇ ਜਾਂਚ ਤੋਂ ਬਾਅਦ ਹੀ ਜਨਤਕ ਹੁੰਦੇ ਹਨ। ਤੁਹਾਡਾ ਬਜਟ, ਫੋਨ ਅਤੇ ਈਮੇਲ ਸਿਰਫ਼ ਤੁਹਾਡੇ ਅਤੇ YaarLink ਸਮੀਖਿਅਕਾਂ ਲਈ ਨਿੱਜੀ ਰਹਿੰਦੇ ਹਨ; ਕੈਂਪੇਨ ਈਮੇਲ ਖਾਲੀ ਹੋਣ ਤੇ ਤੁਹਾਡੀ ਅਕਾਊਂਟ ਈਮੇਲ ਸਮੀਖਿਅਕਾਂ ਕੋਲ ਨਿੱਜੀ ਸੰਪਰਕ ਵਜੋਂ ਉਪਲਬਧ ਰਹਿੰਦੀ ਹੈ। ਜਾਂਚ ਦੀ ਸਥਿਤੀ ਲਈ ਡੈਸ਼ਬੋਰਡ ਵੇਖੋ।",
