  "privacy.contactNotice": "ਅਸੀਂ ਤੁਹਾਡੇ ਨਾਮ, ਸੰਪਰਕ ਵੇਰਵਿਆਂ ਅਤੇ ਸੁਨੇਹੇ ਨੂੰ ਸਿਰਫ਼ ਇਸ ਪੁੱਛਗਿੱਛ ਦਾ ਜਵਾਬ ਦੇਣ ਅਤੇ ਇਸ ਨੂੰ ਸੰਭਾਲਣ ਲਈ ਵਰਤਦੇ ਹਾਂ। ਪਾਸਵਰਡ, ਇੱਕ-ਵਾਰੀ ਕੋਡ ਜਾਂ ਪੇਮੈਂਟ ਵੇਰਵੇ ਨਾ ਭੇਜੋ।",
  "privacy.reportNotice": "ਇਹ ਰਿਪੋਰਟ YaarLink ਮਾਡਰੇਟਰਾਂ ਨੂੰ ਜਾਂਦੀ ਹੈ। ਤੁਹਾਡਾ ਵਿਕਲਪਿਕ ਸੰਪਰਕ ਸਿਰਫ਼ ਫਾਲੋ-ਅੱਪ ਲਈ ਵਰਤਿਆ ਜਾਵੇਗਾ; ਲਾਗ ਇਨ ਹੋਣ 'ਤੇ ਦੁਰਵਰਤੋਂ ਰੋਕਣ ਲਈ ਰਿਪੋਰਟ ਅੰਦਰੂਨੀ ਤੌਰ 'ਤੇ ਤੁਹਾਡੇ ਅਕਾਊਂਟ ਨਾਲ ਜੁੜਦੀ ਹੈ।",
  "privacy.applicationEditNotice": "ਇਸ ਕੈਂਪੇਨ ਦਾ ਬ੍ਰਾਂਡ ਇੱਥੇ ਸੇਵ ਕੀਤਾ ਸੰਪਰਕ ਅਤੇ ਸੁਨੇਹਾ ਵੇਖ ਸਕਦਾ ਹੈ। ਸਿਰਫ਼ ਉਹੀ ਸੰਪਰਕ ਵਰਤੋ ਜੋ ਤੁਸੀਂ ਉਸ ਬ੍ਰਾਂਡ ਨੂੰ ਦੇਣਾ ਚਾਹੁੰਦੇ ਹੋ।",

