function apiErrorKeyFor(status?: number | null, code?: string | null, fallbackKey: TranslationKey = "api.requestFailed"): TranslationKey {
  if (code && API_ERROR_KEYS[code]) return API_ERROR_KEYS[code];
  if (status === 401) return "api.unauthorized";
  if (status === 403) return "api.forbidden";
  if (status === 404) return "api.notFound";
  if (status === 429) return "auth.tooManyRequests";
  if (status === 503) return "api.serviceUnavailable";
  if (status && status >= 500) return "api.requestFailed";
  if (status && status >= 400) return fallbackKey === "api.requestFailed" ? "api.invalidRequest" : fallbackKey;
  return fallbackKey;
}

function formatNumberFor(lang: Lang, value: number, options?: Intl.NumberFormatOptions) {
  return new Intl.NumberFormat(LOCALES[lang], options).format(Number(value || 0));
}

function validationMessageFor(lang: Lang, control: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement) {
  const validity = control.validity;
  const say = (key: TranslationKey, values: Record<string, string> = {}) => {
    let message = translate(lang, key);
    for (const [name, value] of Object.entries(values)) message = message.replace(`{${name}}`, value);
    return message;
  };

  if (validity.valueMissing) {
    if (control instanceof HTMLInputElement && control.type === "checkbox") return say("validation.checkbox");
    if (control instanceof HTMLSelectElement) return say("validation.select");
    return say("validation.required");
  }
  if (validity.typeMismatch) {
    if (control instanceof HTMLInputElement && control.type === "email") return say("validation.email");
    if (control instanceof HTMLInputElement && control.type === "url") return say("validation.url");
    return say("validation.badInput");
  }
  if (validity.patternMismatch) return say("validation.pattern");
  if (validity.tooShort) {
    const min = "minLength" in control && control.minLength > 0 ? control.minLength : 0;
    return say("validation.tooShort", { min: formatNumberFor(lang, min), length: formatNumberFor(lang, control.value.length) });
  }
  if (validity.tooLong) {
    const max = "maxLength" in control && control.maxLength > 0 ? control.maxLength : 0;
    return say("validation.tooLong", { max: formatNumberFor(lang, max), length: formatNumberFor(lang, control.value.length) });
  }
  if (validity.rangeUnderflow && control instanceof HTMLInputElement) {
    return say("validation.rangeUnderflow", { min: formatNumberFor(lang, Number(control.min || 0)) });
  }
  if (validity.rangeOverflow && control instanceof HTMLInputElement) {
    return say("validation.rangeOverflow", { max: formatNumberFor(lang, Number(control.max || 0)) });
  }
  if (validity.stepMismatch) return say("validation.step");
  if (validity.badInput) return say("validation.badInput");
  return say("validation.generic");
}

const ROUTE_TITLES: Record<string, TranslationKey> = {
  "/brands": "brand.eyebrow",
  "/creators": "nav.creators",
  "/campaigns": "nav.campaigns",
  "/how-it-works": "nav.how",
  "/about": "nav.about",
  "/contact": "nav.contact",
  "/dashboard": "dash.title",
  "/account": "account.title",
  "/admin": "meta.admin",
  "/login": "auth.login",
  "/signup": "nav.signup",
  "/forgot-password": "auth.forgotTitle",
  "/reset-password": "auth.resetTitle",
  "/verify-email": "auth.verifyTitle",
  "/verify-account-email": "auth.verifyAccountTitle",
  "/privacy": "legal.privacy",
  "/terms": "legal.terms",
  "/refund-policy": "legal.refunds",
  "/data-rights": "legal.dataRights",
  "/account-deletion": "legal.accountDeletion",
};

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("en");
  const pathname = usePathname();
  const locale = LOCALES[lang];

  useEffect(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY) as Lang | null;
      if (saved === "hi" || saved === "pa" || saved === "en") setLangState(saved);
    } catch {}
  }, []);

  useEffect(() => {
    try {
      document.documentElement.lang = locale;
      document.documentElement.dir = "ltr";
    } catch {}
  }, [locale]);

  useEffect(() => {
    const titleKey = pathname ? ROUTE_TITLES[pathname] : undefined;
    try {
      document.title = titleKey ? `${translate(lang, titleKey)} · YaarLink` : `YaarLink · ${translate(lang, "foot.tagline")}`;
    } catch {}
  }, [lang, pathname]);

  useEffect(() => {
    const isFormControl = (value: EventTarget | null): value is HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement =>
      value instanceof HTMLInputElement || value instanceof HTMLSelectElement || value instanceof HTMLTextAreaElement;

    const onInvalid = (event: Event) => {
      const control = event.target;
      if (!isFormControl(control) || control.validity.customError) return;
      control.setCustomValidity(validationMessageFor(lang, control));
      control.dataset.yaarlinkLocalizedValidity = "true";
    };

    const clearLocalizedValidity = (event: Event) => {
      const control = event.target;
      if (!isFormControl(control) || control.dataset.yaarlinkLocalizedValidity !== "true") return;
      control.setCustomValidity("");
      delete control.dataset.yaarlinkLocalizedValidity;
    };

    document.querySelectorAll("input, select, textarea").forEach((control) => {
      if (isFormControl(control) && control.dataset.yaarlinkLocalizedValidity === "true") {
        control.setCustomValidity("");
        delete control.dataset.yaarlinkLocalizedValidity;
      }
    });

    document.addEventListener("invalid", onInvalid, true);
    document.addEventListener("input", clearLocalizedValidity, true);
    document.addEventListener("change", clearLocalizedValidity, true);
    return () => {
      document.removeEventListener("invalid", onInvalid, true);
      document.removeEventListener("input", clearLocalizedValidity, true);
      document.removeEventListener("change", clearLocalizedValidity, true);
    };
  }, [lang]);

  const setLang = (l: Lang) => {
    setLangState(l);
    try {
      localStorage.setItem(STORAGE_KEY, l);
    } catch {}
  };

  const value: Ctx = {
    lang,
    locale,
    setLang,
    t: (key) => translate(lang, key),
    opt: (v) => {
      if (!v) return "";
      const localizePart = (part: string) => {
        const canonical = normalizeCategory(part) ?? normalizeLanguage(part) ?? normalizeContentType(part) ?? part;
        return CAT[lang]?.[canonical] ?? LANG[lang]?.[canonical] ?? CTYPE[lang]?.[canonical] ?? canonical;
      };
      return v.split(",").map((part) => localizePart(part.trim())).filter(Boolean).join(", ");
    },
    promo: (v) => {
      if (!v) return "";
      const canonical = normalizePromotionType(v) ?? v;
      return PROMO[lang]?.[canonical] ?? canonical;
    },
    promoDetail: (v) => {
      const canonical = normalizePromotionType(v);
      return canonical ? PROMO_DETAILS[lang][canonical] : { desc: "", example: "" };
    },
    platform: (v) => {
      const canonical = normalizePlatform(v);
      if (canonical === "Both") return translate(lang, "cr.both");
      if (canonical === "Other") return translate(lang, "cr.otherPlat");
      return canonical ?? v ?? "";
    },
    apiErrorKey: (status, code, fallbackKey) => apiErrorKeyFor(status, code, fallbackKey),
    apiError: (status, code, fallbackKey) => translate(lang, apiErrorKeyFor(status, code, fallbackKey)),
    formatNumber: (numberValue, options) => formatNumberFor(lang, numberValue, options),
    formatCompactNumber: (numberValue) => {
      if (!numberValue) return formatNumberFor(lang, 0);
      return formatNumberFor(lang, numberValue, { notation: "compact", maximumFractionDigits: 1 });
    },
    formatCurrency: (numberValue) =>
      formatNumberFor(lang, numberValue, { style: "currency", currency: "INR", maximumFractionDigits: 0 }),
    formatDate: (dateValue, options = { dateStyle: "medium" }) => {
      if (!dateValue) return "";
      const date = dateValue instanceof Date ? dateValue : new Date(dateValue);
      return Number.isNaN(date.getTime()) ? "" : new Intl.DateTimeFormat(locale, options).format(date);
    },
    formatDateTime: (dateValue) => {
      if (!dateValue) return "";
      const date = dateValue instanceof Date ? dateValue : new Date(dateValue);
      return Number.isNaN(date.getTime())
        ? ""
        : new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }).format(date);
    },
  };

  return <LangCtx.Provider value={value}>{children}</LangCtx.Provider>;
}

export function useLang() {
  const ctx = useContext(LangCtx);
  if (!ctx) throw new Error("useLang must be used inside LangProvider");
  return ctx;
}

/** Alias kept so `<LanguageProvider>` in layout.tsx keeps working. */
export const LanguageProvider = LangProvider;
